FUNCTION_BLOCK FB_UCHS_CavernThermodynamicChoke
VAR_INPUT
    (* Master Supervisory Execution Controls *)
    bEnable                         : BOOL;     (* Master supervisory block execution enable *)
    bEmergencyShutdown_ESD          : BOOL;     (* Active-low fail-safe emergency shutdown trip from SIS (SIL-3) *)
    bResetFault                     : BOOL;     (* Operator manual fault and alarm latch reset request *)
    bInjectionModeSelect            : BOOL;     (* TRUE = Hydrogen injection into cavern; FALSE = Hydrogen withdrawal *)

    (* Triple Modular Redundancy (2oo3) Wellhead Pressure Sensors *)
    rWellheadPress_A_bar            : REAL;     (* Wellhead pressure transmitter channel A [bar] *)
    rWellheadPress_B_bar            : REAL;     (* Wellhead pressure transmitter channel B [bar] *)
    rWellheadPress_C_bar            : REAL;     (* Wellhead pressure transmitter channel C [bar] *)

    (* Process Thermodynamic Physical Measurements *)
    rWellheadTemp_degC              : REAL;     (* Wellhead hydrogen temperature transmitter [deg C] *)
    rDownholePress_bar              : REAL;     (* Deep subsurface salt cavern core pressure [bar] *)
    rDownholeTemp_degC              : REAL;     (* Deep subsurface salt cavern gas temperature [deg C] *)
    rFlowRate_kg_s                  : REAL;     (* High-pressure Coriolis mass flowmeter [kg/s] *)
    rPipelineHeaderPress_bar        : REAL;     (* Downstream pipeline distribution header pressure [bar] *)

    (* Geomechanical Inventory and Salt Integrity Boundary Limits *)
    rTotalInventoryMass_ton         : REAL;     (* Total dynamic in-situ mass inventory in cavern [ton] *)
    rCushionGasMassTarget_ton       : REAL;     (* Geomechanical minimum cushion gas mass threshold [ton] *)
    rMaxWorkingGasMass_ton          : REAL;     (* Maximum geomechanical structural capacity limit [ton] *)
    rDeliveryTargetPress_bar        : REAL;     (* Grid dispatch target delivery pressure [bar] *)
    rMaxAllowableDepletionRate_bar_hr: REAL;    (* Halite creep & micro-crack convergence pressure limit [bar/hr] *)

    (* Actuator Feedback and Task Cyclic Timing *)
    rChokeFeedback_pct              : REAL;     (* Severe-service thermodynamic choke valve position feedback [%] *)
    rCycleTime_s                    : REAL;     (* PLC cyclic task scan period delta t [s] (e.g. 0.050 s) *)
END_VAR

VAR_OUTPUT
    (* Supervisory Status and Actuator Demands *)
    bSystemReady                    : BOOL;     (* Supervisory ready status for cavern thermodynamic throttle *)
    bActiveControl                  : BOOL;     (* Valve control loop is actively regulating process *)
    rChokeDemand_pct                : REAL;     (* Regulated choke valve actuator command [%] (0.0 to 100.0) *)

    (* Gas Inventory and Cushion Gas Ratio Monitoring *)
    rCushionGasRatio_pct            : REAL;     (* Ratio of cushion gas to current total stored mass [%] *)
    rWorkingGasMass_ton             : REAL;     (* Dynamic extractable working gas mass inventory [ton] *)
    rDepletionRate_bar_hr           : REAL;     (* Calculated salt cavern pressure rate of change [bar/hr] *)

    (* Thermodynamic Phenomenological Outputs *)
    rJouleThomsonDeltaT_K           : REAL;     (* Calculated Joule-Thomson temperature variation across choke [K] *)
    rPredictedThroatTemp_degC       : REAL;     (* Thermodynamic throat orifice temperature [deg C] *)
    rCompressibilityFactor_Z        : REAL;     (* Dynamic real-gas compressibility factor Z [-] *)
    rDensity_kg_m3                  : REAL;     (* High-pressure hydrogen stream density [kg/m3] *)

    (* Alarms, Trip Signals, and Status Bitmasks *)
    bChokeFreezeWarning             : BOOL;     (* Gas hydrate / cryogenic freeze-up risk alarm *)
    bGeomechanicalViolation         : BOOL;     (* Cavern depressurization rate limit exceeded alarm *)
    bCushionGasBreached             : BOOL;     (* Working gas depleted below cushion boundary alarm *)
    bTMRSensorDegraded              : BOOL;     (* 2oo3 sensor voter degradation warning (single channel loss) *)
    bTMRSensorFault                 : BOOL;     (* 2oo3 sensor voter failure trip (dual or triple channel loss) *)
    wOperatingState                 : WORD;     (* Hexadecimal operating state indicator *)
    dwAlarmWord                     : DWORD;    (* Bit-mapped safety, diagnostic, and interlock alarm word *)
END_VAR

VAR
    (* Internal State Machine Sequencing *)
    iState                          : INT := 0; (* Execution state index *)
    iPrevState                      : INT := 0; (* Prior execution state index *)
    tStateTimer                     : TON;      (* State residence dwell timer *)

    (* Triple Modular Redundant (2oo3) Voting Engine Variables *)
    rVotedWellheadPress_bar         : REAL;     (* Voted reliable wellhead pressure [bar] *)
    bChanAFault                     : BOOL;     (* Channel A deviation or range fault *)
    bChanBFault                     : BOOL;     (* Channel B deviation or range fault *)
    bChanCFault                     : BOOL;     (* Channel C deviation or range fault *)
    iHealthySensorsCount            : INT;      (* Number of operational wellhead pressure sensors *)
    rDiffAB                         : REAL;     (* Sensor discrepancy magnitude between A and B [bar] *)
    rDiffBC                         : REAL;     (* Sensor discrepancy magnitude between B and C [bar] *)
    rDiffCA                         : REAL;     (* Sensor discrepancy magnitude between C and A [bar] *)

    (* First-Order Digital Filter and Rate-of-Change Differentiators *)
    rVotedPressPrev_bar             : REAL;     (* Previous cycle voted wellhead pressure [bar] *)
    rCavernPressFiltered_bar        : REAL;     (* Low-pass filtered cavern core pressure [bar] *)
    rCavernPressPrev_bar            : REAL;     (* Previous cycle filtered cavern core pressure [bar] *)
    rDepletionFilterBuffer          : ARRAY[0..9] OF REAL; (* Moving window buffer for depletion rate *)
    iDepletionIdx                   : INT := 0;
    rDepletionSum                   : REAL;
    iLoopIdx                        : INT;

    (* Hydrogen Thermodynamic Parameterization (BWR / Redlich-Kwong Approximation) *)
    rTempKelvin                     : REAL;     (* Absolute wellhead temperature [K] *)
    rReducedPress                   : REAL;     (* P / P_critical ratio [-] *)
    rReducedTemp                    : REAL;     (* T / T_critical ratio [-] *)
    rJouleThomsonCoeff_K_bar        : REAL;     (* Dynamic Joule-Thomson coefficient mu_JT [K/bar] *)
    rPressureDrop_bar               : REAL;     (* Thermodynamic pressure differential over choke orifice [bar] *)

    (* Discrete State-Space Dynamic Model Matrices [A, B, C, D, E] *)
    (* States x = [e_P (bar), dP/dt (bar/s), u_valve (%)]^T *)
    (* Input u = [du_cmd (%/s)] *)
    (* Disturbance d = [P_pipeline (bar), Flow_kg_s (kg/s)]^T *)
    arrA                            : ARRAY[1..3, 1..3] OF REAL; (* Discrete System Dynamics Matrix A *)
    arrB                            : ARRAY[1..3, 1..1] OF REAL; (* Discrete Actuator Input Matrix B *)
    arrC                            : ARRAY[1..2, 1..3] OF REAL; (* Output Observation Matrix C *)
    arrD                            : ARRAY[1..2, 1..1] OF REAL; (* Direct Feedthrough Matrix D *)
    arrE                            : ARRAY[1..3, 1..2] OF REAL; (* Measurable Disturbance Coupling Matrix E *)

    (* Model Predictive Control (MPC) Receding Horizon Quadratic Cost Approximator *)
    (* Weights: Q (state error), R (control effort), S (choke slew rate) *)
    rWeightQ_eP                     : REAL := 12.5; (* State error tracking weight *)
    rWeightQ_dRate                  : REAL := 8.0;  (* Depletion rate damping weight *)
    rWeightR_effort                 : REAL := 0.25; (* Actuator command energy penalty *)
    rWeightS_slew                   : REAL := 2.50; (* Valve wear reduction slew penalty *)

    (* MPC Optimal State Feedback and Feedforward Gain Vectors *)
    arrK_x                          : ARRAY[1..3] OF REAL; (* Closed-loop state feedback vector *)
    arrK_d                          : ARRAY[1..2] OF REAL; (* Disturbance feedforward compensator vector *)

    (* Estimated Internal States *)
    rState_eP                       : REAL;     (* State x1: Pressure regulation error [bar] *)
    rState_dRate                    : REAL;     (* State x2: Cavern pressure rate [bar/s] *)
    rState_uChoke                   : REAL;     (* State x3: Filtered choke valve opening [%] *)

    (* Computed Control Signals & Limits *)
    rRawDeltaDemand_pct             : REAL;     (* Unconstrained MPC delta command [%] *)
    rTargetDemand_pct               : REAL;     (* Target actuator position [%] *)
    rChokeCommandPrev_pct           : REAL;     (* Previous cycle choke demand command [%] *)
    rMaxSlewRate_pct_s              : REAL := 5.0; (* Maximum allowable valve slew rate [%/s] *)

    (* Degradation and Alarm Management *)
    bDegradedSingleSensorActive     : BOOL;     (* Operating in degraded single-sensor fail-safe mode *)
    bThermalQuenchActive            : BOOL;     (* Thermal quench overrides applied to protect choke trims *)
    tFreezeDwellTimer               : TON;      (* Sub-zero temperature persistence qualification timer *)
    tDepletionViolationTimer        : TON;      (* Geomechanical strain rate violation qualification timer *)
END_VAR

VAR_CONSTANT
    (* Physical and Thermodynamic Constants for Pure Hydrogen (H2) *)
    R_SPECIFIC_H2                   : REAL := 4124.2;   (* Specific gas constant for H2 [J/(kg*K)] *)
    CRITICAL_PRESS_BAR              : REAL := 12.96;    (* Critical pressure P_c of hydrogen [bar] *)
    CRITICAL_TEMP_K                 : REAL := 33.145;   (* Critical temperature T_c of hydrogen [K] *)
    JT_INVERSION_TEMP_K             : REAL := 202.0;    (* Joule-Thomson maximum inversion temperature [K] *)
    MAX_SENSOR_DISCREPANCY_BAR      : REAL := 2.50;     (* Permissible deviation threshold between 2oo3 sensors [bar] *)
    MIN_SENSOR_VALID_PRESS_BAR      : REAL := 5.00;     (* Sensor out-of-range low cutoff [bar] *)
    MAX_SENSOR_VALID_PRESS_BAR      : REAL := 250.00;   (* Sensor out-of-range high cutoff [bar] *)

    (* State Machine Step Index Definitions *)
    STATE_IDLE_OFFLINE              : INT := 0;
    STATE_PRE_QUALIFICATION         : INT := 10;
    STATE_TMR_SENSOR_VALIDATION     : INT := 20;
    STATE_THERMODYNAMIC_EVAL        : INT := 30;
    STATE_ACTIVE_MPC_REGULATION     : INT := 40;
    STATE_DEGRADED_OPERATION        : INT := 50;
    STATE_GEOMECHANICAL_HOLD        : INT := 80;
    STATE_EMERGENCY_FAILSAFE        : INT := 90;
END_VAR

(* ========================================================================= *)
(* 0.0 SAFETY INSTRUMENTED INTERLOCKS (SIL-3 FAST PATH EXECUTION)            *)
(* ========================================================================= *)
IF NOT bEmergencyShutdown_ESD THEN
    (* Fail-Safe De-energized Trip State: Immediate Choke Closure *)
    rChokeDemand_pct        := 0.0;
    bSystemReady            := FALSE;
    bActiveControl          := FALSE;
    dwAlarmWord.0           := TRUE; (* ESD Trip Active Bit *)
    wOperatingState         := 16#9000;
    iState                  := STATE_EMERGENCY_FAILSAFE;
    RETURN;
END_IF;

(* Delta-t guard condition for safe real-time numerical integration *)
IF rCycleTime_s <= 0.001 THEN
    rCycleTime_s := 0.050; (* Default to 50ms cyclic task scan period *)
END_IF;

(* Reset latched alarms upon operator reset pulse *)
IF bResetFault THEN
    dwAlarmWord := 16#00000000;
    bChokeFreezeWarning := FALSE;
    bGeomechanicalViolation := FALSE;
    bCushionGasBreached := FALSE;
    bTMRSensorFault := FALSE;
END_IF;

(* ========================================================================= *)
(* 1.0 TRIPLE MODULAR REDUNDANCY (2oo3) VOTING AND FAULT DETECTION           *)
(* ========================================================================= *)
(* Channel Range Diagnostics *)
bChanAFault := (rWellheadPress_A_bar < MIN_SENSOR_VALID_PRESS_BAR) OR (rWellheadPress_A_bar > MAX_SENSOR_VALID_PRESS_BAR);
bChanBFault := (rWellheadPress_B_bar < MIN_SENSOR_VALID_PRESS_BAR) OR (rWellheadPress_B_bar > MAX_SENSOR_VALID_PRESS_BAR);
bChanCFault := (rWellheadPress_C_bar < MIN_SENSOR_VALID_PRESS_BAR) OR (rWellheadPress_C_bar > MAX_SENSOR_VALID_PRESS_BAR);

(* Cross-Channel Deviation Discrepancy Calculations *)
rDiffAB := ABS(rWellheadPress_A_bar - rWellheadPress_B_bar);
rDiffBC := ABS(rWellheadPress_B_bar - rWellheadPress_C_bar);
rDiffCA := ABS(rWellheadPress_C_bar - rWellheadPress_A_bar);

(* Discrepancy Fault Isolation *)
IF (rDiffAB > MAX_SENSOR_DISCREPANCY_BAR) AND (rDiffCA > MAX_SENSOR_DISCREPANCY_BAR) THEN
    bChanAFault := TRUE;
END_IF;
IF (rDiffAB > MAX_SENSOR_DISCREPANCY_BAR) AND (rDiffBC > MAX_SENSOR_DISCREPANCY_BAR) THEN
    bChanBFault := TRUE;
END_IF;
IF (rDiffBC > MAX_SENSOR_DISCREPANCY_BAR) AND (rDiffCA > MAX_SENSOR_DISCREPANCY_BAR) THEN
    bChanCFault := TRUE;
END_IF;

(* Calculate Population of Healthy Transmitters *)
iHealthySensorsCount := 0;
IF NOT bChanAFault THEN iHealthySensorsCount := iHealthySensorsCount + 1; END_IF;
IF NOT bChanBFault THEN iHealthySensorsCount := iHealthySensorsCount + 1; END_IF;
IF NOT bChanCFault THEN iHealthySensorsCount := iHealthySensorsCount + 1; END_IF;

(* 2oo3 Voter Degradation Logic *)
CASE iHealthySensorsCount OF
    3:
        (* Nominal 2oo3 Median Selection Strategy *)
        IF (rWellheadPress_A_bar >= rWellheadPress_B_bar AND rWellheadPress_A_bar <= rWellheadPress_C_bar) OR
           (rWellheadPress_A_bar <= rWellheadPress_B_bar AND rWellheadPress_A_bar >= rWellheadPress_C_bar) THEN
            rVotedWellheadPress_bar := rWellheadPress_A_bar;
        ELSIF (rWellheadPress_B_bar >= rWellheadPress_A_bar AND rWellheadPress_B_bar <= rWellheadPress_C_bar) OR
              (rWellheadPress_B_bar <= rWellheadPress_A_bar AND rWellheadPress_B_bar >= rWellheadPress_C_bar) THEN
            rVotedWellheadPress_bar := rWellheadPress_B_bar;
        ELSE
            rVotedWellheadPress_bar := rWellheadPress_C_bar;
        END_IF;
        bTMRSensorDegraded          := FALSE;
        bTMRSensorFault             := FALSE;
        bDegradedSingleSensorActive := FALSE;

    2:
        (* Degraded 1oo2 Average Voter *)
        IF NOT bChanAFault AND NOT bChanBFault THEN
            rVotedWellheadPress_bar := 0.5 * (rWellheadPress_A_bar + rWellheadPress_B_bar);
        ELSIF NOT bChanBFault AND NOT bChanCFault THEN
            rVotedWellheadPress_bar := 0.5 * (rWellheadPress_B_bar + rWellheadPress_C_bar);
        ELSE
            rVotedWellheadPress_bar := 0.5 * (rWellheadPress_A_bar + rWellheadPress_C_bar);
        END_IF;
        bTMRSensorDegraded          := TRUE;
        bTMRSensorFault             := FALSE;
        bDegradedSingleSensorActive := FALSE;
        dwAlarmWord.1               := TRUE; (* Sensor degradation alarm flag *)

    1:
        (* Degraded Single-Sensor Mode with Conservative Operation *)
        IF NOT bChanAFault THEN
            rVotedWellheadPress_bar := rWellheadPress_A_bar;
        ELSIF NOT bChanBFault THEN
            rVotedWellheadPress_bar := rWellheadPress_B_bar;
        ELSE
            rVotedWellheadPress_bar := rWellheadPress_C_bar;
        END_IF;
        bTMRSensorDegraded          := TRUE;
        bTMRSensorFault             := FALSE;
        bDegradedSingleSensorActive := TRUE;
        dwAlarmWord.2               := TRUE; (* Critical sensor loss - single channel operation *)

    0:
        (* Total Sensor Failure -> Fail-Safe Trip *)
        rVotedWellheadPress_bar     := 0.0;
        bTMRSensorDegraded          := TRUE;
        bTMRSensorFault             := TRUE;
        dwAlarmWord.3               := TRUE; (* 2oo3 Voter complete loss of signal trip *)
        iState                      := STATE_EMERGENCY_FAILSAFE;
END_CASE;

(* ========================================================================= *)
(* 2.0 THERMODYNAMIC JOULE-THOMSON & REAL-GAS EOS EVALUATION                 *)
(* ========================================================================= *)
rTempKelvin := rWellheadTemp_degC + 273.15;
IF rTempKelvin < 150.0 THEN
    rTempKelvin := 150.0; (* Thermal clamp for numerical stability *)
END_IF;

(* Dimensionless Reduced State Variables for H2 Equation of State *)
rReducedPress := rVotedWellheadPress_bar / CRITICAL_PRESS_BAR;
rReducedTemp  := rTempKelvin / CRITICAL_TEMP_K;

(* Truncated Virial Equation of State Compressibility Factor Z(P, T) for H2 *)
(* Empirical correlation for high pressure subterranean hydrogen regimes *)
rCompressibilityFactor_Z := 1.0 + (0.000647 * rVotedWellheadPress_bar) 
                            - (0.0152 * (rVotedWellheadPress_bar / rTempKelvin))
                            + (0.00000185 * (rVotedWellheadPress_bar * rVotedWellheadPress_bar));

IF rCompressibilityFactor_Z < 0.85 THEN
    rCompressibilityFactor_Z := 0.85;
ELSIF rCompressibilityFactor_Z > 1.45 THEN
    rCompressibilityFactor_Z := 1.45;
END_IF;

(* Real Gas Density Evaluation [kg/m^3]: P [Pa] / (Z * R * T [K]) *)
rDensity_kg_m3 := (rVotedWellheadPress_bar * 100000.0) / (rCompressibilityFactor_Z * R_SPECIFIC_H2 * rTempKelvin);

(* Dynamic Joule-Thomson Coefficient mu_JT [K/bar] Formulation *)
(* For Hydrogen: Inversion temperature is ~202K (-71C). Above 202K, JT expansion warms gas (mu_JT < 0). *)
(* Below 202K or during high-pressure supercritical throttling, cooling or reverse thermal shocks occur. *)
rPressureDrop_bar := rVotedWellheadPress_bar - rPipelineHeaderPress_bar;

IF rTempKelvin > JT_INVERSION_TEMP_K THEN
    (* Heating upon expansion: negative JT coefficient *)
    rJouleThomsonCoeff_K_bar := -0.055 * (1.0 - (JT_INVERSION_TEMP_K / rTempKelvin));
ELSE
    (* Cooling upon expansion: positive JT coefficient -> hydrate and valve freeze danger! *)
    rJouleThomsonCoeff_K_bar := 0.082 * ((JT_INVERSION_TEMP_K / rTempKelvin) - 1.0);
END_IF;

(* Calculated Joule-Thomson Temperature Change [K] across throttling orifice *)
rJouleThomsonDeltaT_K := rJouleThomsonCoeff_K_bar * rPressureDrop_bar;

(* Predicted Throat Orifice Temperature [deg C] *)
rPredictedThroatTemp_degC := rWellheadTemp_degC + rJouleThomsonDeltaT_K;

(* Cryogenic Freezing & Hydrate Formation Monitoring *)
tFreezeDwellTimer(IN := (rPredictedThroatTemp_degC < -5.0), PT := T#3S);
IF tFreezeDwellTimer.Q THEN
    bChokeFreezeWarning := TRUE;
    dwAlarmWord.4       := TRUE; (* Cryogenic Joule-Thomson choke freeze warning *)
END_IF;

(* ========================================================================= *)
(* 3.0 CUSHION GAS MASS RATIO & GEOMECHANICAL ROCK CONVERGENCE MONITORING    *)
(* ========================================================================= *)
(* Dynamic Working Gas Inventory [ton] *)
rWorkingGasMass_ton := rTotalInventoryMass_ton - rCushionGasMassTarget_ton;

(* Cushion Gas Mass Ratio relative to total inventory [%] *)
IF rTotalInventoryMass_ton > 0.1 THEN
    rCushionGasRatio_pct := (rCushionGasMassTarget_ton / rTotalInventoryMass_ton) * 100.0;
ELSE
    rCushionGasRatio_pct := 100.0;
END_IF;

(* Cushion Gas Boundary Violation Check *)
IF rWorkingGasMass_ton <= 0.0 THEN
    bCushionGasBreached := TRUE;
    dwAlarmWord.5       := TRUE; (* Cushion gas integrity compromised *)
END_IF;

(* Low-Pass Filter on Cavern Core Downhole Pressure *)
rCavernPressFiltered_bar := (0.95 * rCavernPressFiltered_bar) + (0.05 * rDownholePress_bar);

(* Sliding Window Depletion Rate Calculation [bar/hr] *)
(* dp/dt = (P_current - P_previous) / dt * 3600 *)
rDepletionFilterBuffer[iDepletionIdx] := (rCavernPressFiltered_bar - rCavernPressPrev_bar) * (3600.0 / rCycleTime_s);
rCavernPressPrev_bar := rCavernPressFiltered_bar;

iDepletionIdx := (iDepletionIdx + 1) MOD 10;
rDepletionSum := 0.0;
FOR iLoopIdx := 0 TO 9 DO
    rDepletionSum := rDepletionSum + rDepletionFilterBuffer[iLoopIdx];
END_FOR;
rDepletionRate_bar_hr := rDepletionSum / 10.0;

(* Geomechanical Salt Cavern Convergence Protection *)
tDepletionViolationTimer(
    IN := (ABS(rDepletionRate_bar_hr) > rMaxAllowableDepletionRate_bar_hr) AND (rMaxAllowableDepletionRate_bar_hr > 0.01),
    PT := T#5S
);

IF tDepletionViolationTimer.Q THEN
    bGeomechanicalViolation := TRUE;
    dwAlarmWord.6           := TRUE; (* Halite salt creep / shear fracture hazard *)
END_IF;

(* ========================================================================= *)
(* 4.0 STATE-SPACE MATRICES INITIALIZATION & MPC GAIN CONFIGURATION          *)
(* ========================================================================= *)
(* Discrete System State Transition Matrix A (3x3) *)
arrA[1, 1] := 0.9450; arrA[1, 2] := 0.0480; arrA[1, 3] := -0.1250;
arrA[2, 1] := -0.012; arrA[2, 2] := 0.8920; arrA[2, 3] := -0.2100;
arrA[3, 1] := 0.0000; arrA[3, 2] := 0.0000; arrA[3, 3] := 0.8200;

(* Actuator Input Coupling Matrix B (3x1) *)
arrB[1, 1] := 0.0650;
arrB[2, 1] := 0.1150;
arrB[3, 1] := 0.1800;

(* Output Observation Matrix C (2x3) *)
arrC[1, 1] := 1.0; arrC[1, 2] := 0.0; arrC[1, 3] := 0.0;
arrC[2, 1] := 0.0; arrC[2, 2] := 1.0; arrC[2, 3] := 0.0;

(* Direct Feedthrough Matrix D (2x1) *)
arrD[1, 1] := 0.0;
arrD[2, 1] := 0.0;

(* Disturbance Input Matrix E (3x2) *)
arrE[1, 1] := -0.035; arrE[1, 2] := 0.012;
arrE[2, 1] := -0.065; arrE[2, 2] := 0.024;
arrE[3, 1] := 0.0000; arrE[3, 2] := 0.000;

(* Stationary Riccati / Quadratic Cost MPC Feedback Gains K_x and K_d *)
arrK_x[1] := 1.845;  (* State feedback gain on pressure tracking error *)
arrK_x[2] := 0.720;  (* State feedback gain on cavern pressure gradient *)
arrK_x[3] := 0.315;  (* Internal valve state feedback *)

arrK_d[1] := -0.420; (* Feedforward gain on pipeline header back-pressure *)
arrK_d[2] := 0.085;  (* Feedforward gain on gas Coriolis mass flow rate *)

(* Calculate Current State Vector x = [x1, x2, x3]^T *)
rState_eP     := rVotedWellheadPress_bar - rDeliveryTargetPress_bar;
rState_dRate  := (rVotedWellheadPress_bar - rVotedPressPrev_bar) / rCycleTime_s;
rState_uChoke := rChokeFeedback_pct;
rVotedPressPrev_bar := rVotedWellheadPress_bar;

(* ========================================================================= *)
(* 5.0 SUPERVISORY MULTI-STAGE CASE MACHINE & MPC THROTTLE ENGINE            *)
(* ========================================================================= *)
tStateTimer(IN := (iState = iPrevState), PT := T#24H);
iPrevState := iState;

CASE iState OF

    STATE_IDLE_OFFLINE: (* 0: System Idle & Valve Parked *)
        wOperatingState   := 16#0000;
        bSystemReady      := FALSE;
        bActiveControl    := FALSE;
        rChokeDemand_pct  := 0.0;
        rChokeCommandPrev_pct := 0.0;

        IF bEnable AND (NOT bTMRSensorFault) AND (NOT dwAlarmWord.0) THEN
            iState := STATE_PRE_QUALIFICATION;
        END_IF;

    STATE_PRE_QUALIFICATION: (* 10: Inventory and Permissive Verification *)
        wOperatingState   := 16#000A;
        bSystemReady      := FALSE;
        bActiveControl    := FALSE;
        rChokeDemand_pct  := 0.0;

        (* Check cushion gas integrity and valid pipeline delivery targets *)
        IF (rWorkingGasMass_ton > 1.0) AND (rDeliveryTargetPress_bar > 1.0) AND (NOT bCushionGasBreached) THEN
            iState := STATE_TMR_SENSOR_VALIDATION;
        ELSIF rWorkingGasMass_ton <= 1.0 THEN
            bCushionGasBreached := TRUE;
            dwAlarmWord.5       := TRUE;
            iState := STATE_GEOMECHANICAL_HOLD;
        END_IF;

        IF NOT bEnable THEN
            iState := STATE_IDLE_OFFLINE;
        END_IF;

    STATE_TMR_SENSOR_VALIDATION: (* 20: 2oo3 Sensor Sanity Verification *)
        wOperatingState   := 16#0014;
        bSystemReady      := TRUE;
        bActiveControl    := FALSE;

        IF bTMRSensorFault THEN
            iState := STATE_EMERGENCY_FAILSAFE;
        ELSIF bTMRSensorDegraded THEN
            iState := STATE_DEGRADED_OPERATION;
        ELSE
            iState := STATE_THERMODYNAMIC_EVAL;
        END_IF;

    STATE_THERMODYNAMIC_EVAL: (* 30: Joule-Thomson Conditioning & Safe Envelopes *)
        wOperatingState   := 16#001E;
        bSystemReady      := TRUE;
        bActiveControl    := FALSE;

        (* Evaluate pre-start thermal risks *)
        IF bChokeFreezeWarning THEN
            (* Actuate auxiliary trim warming or transition to degraded throttled opening *)
            iState := STATE_DEGRADED_OPERATION;
        ELSE
            iState := STATE_ACTIVE_MPC_REGULATION;
        END_IF;

    STATE_ACTIVE_MPC_REGULATION: (* 40: Closed-Loop Receding Horizon Control *)
        wOperatingState   := 16#0028;
        bSystemReady      := TRUE;
        bActiveControl    := TRUE;

        (* Check Interlocks and Safety Constraints *)
        IF bGeomechanicalViolation THEN
            iState := STATE_GEOMECHANICAL_HOLD;
        ELSIF bCushionGasBreached THEN
            iState := STATE_GEOMECHANICAL_HOLD;
        ELSIF bTMRSensorDegraded THEN
            iState := STATE_DEGRADED_OPERATION;
        ELSIF bTMRSensorFault THEN
            iState := STATE_EMERGENCY_FAILSAFE;
        ELSIF NOT bEnable THEN
            iState := STATE_IDLE_OFFLINE;
        ELSE
            (* Compute Unconstrained Quadratic Cost State-Feedback MPC Law *)
            (* delta_u = - (K_x * x + K_d * d) *)
            rRawDeltaDemand_pct := - ( (arrK_x[1] * rState_eP)
                                     + (arrK_x[2] * rState_dRate)
                                     + (arrK_x[3] * (rChokeCommandPrev_pct - rChokeFeedback_pct))
                                     + (arrK_d[1] * (rPipelineHeaderPress_bar - rDeliveryTargetPress_bar))
                                     + (arrK_d[2] * rFlowRate_kg_s) );

            (* Dynamic Slew Rate Limiter to Mitigate Acoustic Vibration & Halite Micro-Cracking *)
            IF rRawDeltaDemand_pct > (rMaxSlewRate_pct_s * rCycleTime_s) THEN
                rRawDeltaDemand_pct := rMaxSlewRate_pct_s * rCycleTime_s;
            ELSIF rRawDeltaDemand_pct < -(rMaxSlewRate_pct_s * rCycleTime_s) THEN
                rRawDeltaDemand_pct := -(rMaxSlewRate_pct_s * rCycleTime_s);
            END_IF;

            (* Actuator Target Accumulation *)
            rTargetDemand_pct := rChokeCommandPrev_pct + rRawDeltaDemand_pct;

            (* Severe Service Choke Trim Protection: Anti-Freeze Throttling Clamp *)
            IF (rPredictedThroatTemp_degC < 2.0) AND (rPressureDrop_bar > 40.0) THEN
                (* Constrain maximum opening to avert deep cryogenic hydrate plug *)
                IF rTargetDemand_pct > 65.0 THEN
                    rTargetDemand_pct := 65.0;
                END_IF;
            END_IF;

            (* Actuator Output Saturation Envelopes [0.0% to 100.0%] *)
            IF rTargetDemand_pct > 100.0 THEN
                rChokeDemand_pct := 100.0;
            ELSIF rTargetDemand_pct < 0.0 THEN
                rChokeDemand_pct := 0.0;
            ELSE
                rChokeDemand_pct := rTargetDemand_pct;
            END_IF;

            rChokeCommandPrev_pct := rChokeDemand_pct;
        END_IF;

    STATE_DEGRADED_OPERATION: (* 50: Graceful Degradation (Conservative Slew & Margins) *)
        wOperatingState   := 16#0032;
        bSystemReady      := TRUE;
        bActiveControl    := TRUE;

        IF bTMRSensorFault THEN
            iState := STATE_EMERGENCY_FAILSAFE;
        ELSIF bGeomechanicalViolation OR bCushionGasBreached THEN
            iState := STATE_GEOMECHANICAL_HOLD;
        ELSE
            (* Restrict Slew Rate and Valve Opening in Degraded Multi-Channel Loss *)
            rRawDeltaDemand_pct := - ( (1.0 * rState_eP) + (0.3 * rState_dRate) );

            (* Tighter Slew Limiter for Degraded State *)
            IF rRawDeltaDemand_pct > (1.5 * rCycleTime_s) THEN
                rRawDeltaDemand_pct := 1.5 * rCycleTime_s;
            ELSIF rRawDeltaDemand_pct < -(1.5 * rCycleTime_s) THEN
                rRawDeltaDemand_pct := -(1.5 * rCycleTime_s);
            END_IF;

            rTargetDemand_pct := rChokeCommandPrev_pct + rRawDeltaDemand_pct;

            (* Clamp Maximum Choke Valve Output to 50% During Degraded Operation *)
            IF rTargetDemand_pct > 50.0 THEN
                rChokeDemand_pct := 50.0;
            ELSIF rTargetDemand_pct < 0.0 THEN
                rChokeDemand_pct := 0.0;
            ELSE
                rChokeDemand_pct := rTargetDemand_pct;
            END_IF;

            rChokeCommandPrev_pct := rChokeDemand_pct;

            (* Recover to Normal MPC if Sensor Health Restored and No Freeze Alarm *)
            IF (iHealthySensorsCount = 3) AND (NOT bChokeFreezeWarning) THEN
                iState := STATE_ACTIVE_MPC_REGULATION;
            END_IF;
        END_IF;

    STATE_GEOMECHANICAL_HOLD: (* 80: Rock Salt Convergence Envelope Hold *)
        wOperatingState   := 16#0050;
        bSystemReady      := FALSE;
        bActiveControl    := FALSE;

        (* Controlled Smooth Linear Ramping to Zero Flow (Anti-Hydraulic Hammer) *)
        IF rChokeDemand_pct > 0.5 THEN
            rChokeDemand_pct := rChokeDemand_pct - (2.0 * rCycleTime_s);
        ELSE
            rChokeDemand_pct := 0.0;
