        rChokeCommandPrev_pct := rChokeDemand_pct;

        (* Allow return to Idle only if fault cleared and reset commanded *)
        IF bResetFault AND (NOT bGeomechanicalViolation) AND (NOT bCushionGasBreached) THEN
            iState := STATE_IDLE_OFFLINE;
        END_IF;

    STATE_EMERGENCY_FAILSAFE: (* 90: SIL-3 Lockout Safe State *)
        wOperatingState   := 16#9000;
        bSystemReady      := FALSE;
        bActiveControl    := FALSE;
        rChokeDemand_pct  := 0.0;
        rChokeCommandPrev_pct := 0.0;

        (* Require Master Enable low, SIS Healthy, and explicit reset pulse *)
        IF (NOT bEnable) AND bEmergencyShutdown_ESD AND bResetFault AND (NOT bTMRSensorFault) THEN
            iState := STATE_IDLE_OFFLINE;
        END_IF;

    ELSE
        (* Defensive Fallback for Corrupted State Register *)
        iState := STATE_EMERGENCY_FAILSAFE;

END_CASE;

